SELECT count(*) AS winners_returned FROM winners;
SELECT status, count(*) FROM jobs GROUP BY 1 ORDER BY 1;
SELECT count(*) AS errmsg_correct FROM jobs j JOIN winners w USING(job_id) WHERE j.error = 'dependency `dep'||(substr(j.job_id,2)::int)||'` finished failed';
